.Lanon.67d5b4929e204ab6db13ba1ac77630c6.489:
	.ascii	"\n        int rechercheBinaire(int tab[],int x,int i, int j){\n            int gau=i, droite=j;\n            while (gau<=droite) {\n                int milieu = (gau+droite)/2;\n                if (tab[milieu]==x)\n                    return milieu;\n                if (tab[milieu]>x)\n                    droite = milieu-1;\n                else\n                    gau = milieu+1;\n            }\n            return -1;\n        }\n\n        int recherche(int tab[],int x,int size) {\n            return rechercheBinaire(tab,x,0,size-1);\n        }\n\n        int search(int it) {\n            int nums[10] = {1, 3, 4, 8, 9, 13, 15, 16, 20, 25};\n            int res = recherche(nums, it, 10); // should return 4\n            return res;\n            return nums[4];\n        }"
	.size	.Lanon.67d5b4929e204ab6db13ba1ac77630c6.489, 757

